/// Async on purpose: creating a window inside a synchronous command deadlocks
/// on Windows (the new window stays white and stops responding; tauri #4121,
/// found in the first Windows test).
///
/// # Errors
/// When the window cannot be created.
#[tauri::command]
#[specta::specta]
pub async fn settings_open<R: Runtime>(app: AppHandle<R>) -> Result<(), CommandError> {
    settings_window::open(&app).map_err(CommandError::from)
}

/// Ask the user for a folder (Settings, F-415). `None` when they cancel.
/// Async, and the dialog answers through a channel, so the event loop never
/// blocks (the same Windows deadlock as `settings_open`).
///
/// # Errors
/// When the dialog cannot be shown or returns a path that isn't a folder path.
#[tauri::command]
#[specta::specta]
pub async fn pick_folder<R: Runtime>(
    window: WebviewWindow<R>,
    title: String,
    start: Option<String>,
) -> Result<Option<String>, CommandError> {
    use tauri_plugin_dialog::DialogExt;

    let (tx, rx) = tokio::sync::oneshot::channel();
    let mut dialog = window.dialog().file().set_parent(&window).set_title(title);
    if let Some(start) = start.filter(|s| std::path::Path::new(s).is_dir()) {
        dialog = dialog.set_directory(start);
    }
    dialog.pick_folder(move |picked| {
        let _ = tx.send(picked);
    });
    let picked = rx.await.map_err(|_| CommandError {
        message: PICKER_FAILED_TEXT.into(),
    })?;
    picked
        .map(|p| {
            p.into_path()
                .map(|path| path.to_string_lossy().into_owned())
                .map_err(|e| {
                    tracing::warn!(error = %e, "picked folder is not a path");
                    CommandError {
                        message: PICKER_FAILED_TEXT.into(),
                    }
                })
        })
        .transpose()
}

const PICKER_FAILED_TEXT: &str = "Couldn't open the folder picker.";

/// Whether this run is the end-to-end smoke test (`EV_SMOKE_TEST=1`).
#[tauri::command]
#[specta::specta]
pub fn smoke_test_mode() -> bool {
    smoke::enabled()
}

/// The UI reached a smoke-test checkpoint.
#[tauri::command]
#[specta::specta]
pub fn smoke_test_step<R: Runtime>(app: AppHandle<R>, step: String) {
    smoke::step(&app, &step);
}

/// Open config.toml in the user's default editor.
///
/// # Errors
/// When no application can open it.
#[tauri::command]
#[specta::specta]
pub fn open_config_file<R: Runtime>(
    app: AppHandle<R>,
    state: State<'_, AppState>,
) -> Result<(), CommandError> {
    let path = state.data_dir.join("config.toml");
    app.opener()
        .open_path(path.to_string_lossy(), None::<&str>)
        .map_err(|e| {
            tracing::warn!(error = %e, "open config file failed");
            CommandError {
                message: "Couldn't open the config file.".into(),
            }
        })
}

